roup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "version": "01.00.000"}, "dimension": "time", "factor": "0.00011415525114155251", "target_unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "version": "01.00.000"}}], "expected": {"action_count": 6, "amount_field_count": 16, "audit_count": 8, "batch_count": 1, "derivative_target_count": 6, "exchange_count": 8, "flow_count": 3, "flowproperty_count": 0, "process_count": 3, "text_action_count": 1, "unrelated_exchange_count": 3}, "plan_sha256": "3ed37f87d621a03237a3a0d004bf00403b3fbba292beebf0ea5bafadb1e276d5", "schema_version": "dataset-alias-plan.v2", "source_alias": {"id": "bd69e542-6a50-524c-8d04-195b1ec23150", "sha256": "458d10de07aa8a2a2cb84d264b991edcbc92d1e0d16fc51064412a76bea132ed", "version": "00.00.001"}, "source_evidence": {"cohort_sha256": "e818cd161bbf48651973f3d93e8ded448ae4be3eb29835d943b8157ed8a58a55", "declared_source_unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "sha256": "2f2a83c829ffaea06cef8e337f81319b686e05e683edae521016168393c699d4", "version": "01.00.000"}, "exchange_count": 8, "expected_cohort_sha256": "e818cd161bbf48651973f3d93e8ded448ae4be3eb29835d943b8157ed8a58a55", "original_source_unit": "hr", "sha256": "1ba7a33399e9f45613d3bcdd27270182d7164b6e2e61f0de2592116b38d39d24", "source_flowproperty": {"id": "bd69e542-6a50-524c-8d04-195b1ec23150", "sha256": "8008aaa69fd0b0aa30bb625b8929a1e0e25184e68101ce121394201dd2f4ebaa", "version": "00.00.001"}}, "target_snapshots": {"flowproperty": {"id": "da11d28f-4db8-51eb-b3a9-8784b26771e6", "sha256": "22a048dc39905cbd8f614af04cfe86145eb3d5c98f2ffad42a9f933baeebc8a1", "version": "01.00.000"}, "unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "sha256": "2f2a83c829ffaea06cef8e337f81319b686e05e683edae521016168393c699d4", "version": "01.00.000"}}, "target_visibility": "owner_draft", "text_actions": [{"after_text": "1.0 hr Fixture unit 1", "before_text": "1.0 a Fixture unit 1", "id": "b20c0de0-0000-4000-8000-000000000001", "source_exchange_number": "730000", "table": "processes", "version": "00.00.001"}]}, "project_ref": "qgzvkongdjqiiamzbbts", "request_id": "fcfbc113-8d7e-575c-a7f3-ba5abfbf2265", "schema_version": "dataset-alias-execution-preflight.v2", "target_visibility": "owner_draft"}$wire$::jsonb as request;
create temp table v2_ctx as
  select 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid as request_id,
         (select request->'plan'->>'plan_sha256' from v2_wire) as plan_sha256;

create or replace function pg_temp.as_actor() returns void language plpgsql as $$
begin
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config('request.jwt.claim.sub', 'c536ee37-64ab-427b-b7e3-4e2bb4fdffb7', true);
  perform set_config('request.jwt.claim.email', 'fixture-owner@example.invalid', true);
end $$;

create or replace function pg_temp.gate_projection(p_result jsonb)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'expected_sha256', p_result->>'expected_sha256',
    'observed_sha256', p_result->>'observed_sha256',
    'status', p_result->>'status',
    'captured_at', p_result->>'captured_at')
$$;

select pg_temp.as_actor();
create temp table v2_pf as
  select api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire)) as result;
create temp table v2_g1 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'primary_support_plan') as result;
create temp table v2_g2 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'execution_unused') as result;
create temp table v2_g3 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'derivative_quiescence') as result;
create temp table v2_admit as
  select api.cmd_dataset_alias_execution_admit_v2_guarded(jsonb_build_object(
    'schema_version', 'dataset-alias-execution-admit.v2',
    'request_id', (select request_id::text from v2_ctx),
    'preflight_token', (select result->>'preflight_token' from v2_pf),
    'preflight_proof_sha256', (select result->>'preflight_proof_sha256' from v2_pf),
    'gate_results', jsonb_build_object(
      'primary_support_plan', pg_temp.gate_projection((select result from v2_g1)),
      'execution_unused', pg_temp.gate_projection((select result from v2_g2)),
      'derivative_quiescence', pg_temp.gate_projection((select result from v2_g3))))) as result;
select is((select result->>'status' from v2_admit), 'dispatched', 'the reviewed request is admitted once');

select set_config('request.headers',
  jsonb_build_object('apikey', util.project_secret_key(), 'authorization', 'Bearer ' || util.project_secret_key())::text, true);
create temp table v2_execute as
  select api.cmd_dataset_alias_execution_execute_v2(
    (select request_id from v2_ctx),
    (select convert_from(queued.body, 'UTF8')::jsonb->>'p_nonce'
     from net.http_request_queue as queued
     join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
     where request.id = (select request_id from v2_ctx))) as result;
select is((select result->>'status' from v2_execute), 'derivatives_pending', 'the executor commits the primary and the derivative closure');

create temp table v2_pending_read as
  select api.cmd_dataset_alias_execution_read_v2((select request_id from v2_ctx)) as result;
select is((select result->>'status' from v2_pending_read), 'pending', 'the read is pending before the worker completes');
select is(
  (select result->'terminal_proof' is not distinct from 'null'::jsonb from v2_pending_read),
  true,
  'a pending execution carries a JSON null terminal proof, never a fabricated observation'
);

do $$
declare
  v_request util.dataset_derivative_rebuild_requests%rowtype;
  v_markdown_id bigint;
  v_embedding_id bigint;
  v_markdown text;
  v_markdown_sha256 text;
  v_embedding extensions.vector;
  v_snapshot jsonb;
  v_batch_ids uuid[];
begin
  select array_agg((chunk->>'batch_id')::uuid) into v_batch_ids
  from util.dataset_alias_execution_v2_requests as request,
       jsonb_array_elements(request.derivative_admission->'chunks') as chunk
  where request.id = 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid;
  v_embedding := ('[' || array_to_string(array_fill('0'::text, array[1024]), ',') || ']')::extensions.vector;
  for v_request in
    select * from util.dataset_derivative_rebuild_requests as derivative
    where derivative.batch_id = any (v_batch_ids)
    order by derivative.batch_id, derivative.batch_ordinal
  loop
    v_markdown := 'accepted worker markdown ' || v_request.id::text;
    v_markdown_sha256 := util.dataset_derivative_rebuild_sha256(v_markdown);
    insert into util.dataset_derivative_rebuild_proposals (request_id, proposal_kind, extracted_md, extracted_md_sha256, status)
    values (v_request.id, 'markdown', v_markdown, v_markdown_sha256, 'accepted') returning id into v_markdown_id;
    insert into util.dataset_derivative_rebuild_proposals (
      request_id, proposal_kind, embedding_ft, embedding_ft_sha256, embedding_ft_at, source_extracted_md_sha256, status)
    values (v_request.id, 'embedding', v_embedding, util.dataset_derivative_rebuild_sha256(v_embedding::text),
      clock_timestamp() + interval '1 second', v_markdown_sha256, 'captured') returning id into v_embedding_id;
    update util.dataset_derivative_rebuild_requests
    set markdown_proposal_id = v_markdown_id, accepted_extracted_md_sha256 = v_markdown_sha256,
        markdown_request_id = -9000000 - v_request.batch_ordinal,
        markdown_dispatched_at = clock_timestamp() - interval '3 seconds',
        markdown_response_status = 200, markdown_response_received_at = clock_timestamp() - interval '2 seconds',
        embedding_queue_msg_id = -8000000 - v_request.batch_ordinal,
        embedding_queued_at = clock_timestamp() - interval '1 second'
    where id = v_request.id;
    perform util.commit_dataset_derivative_rebuild_proposal(v_request.id, v_markdown_id, v_embedding_id);
    v_snapshot := util.dataset_derivative_rebuild_snapshot(v_request.target_table, v_request.target_id, v_request.target_version);
    update util.dataset_derivative_rebuild_requests
    set status = 'completed', phase = 'completed', completed_snapshot_sha256 = v_snapshot->>'snapshot_sha256',
        completed_at = clock_timestamp(), terminal_at = clock_timestamp(), drained_at = clock_timestamp()
    where id = v_request.id;
    perform util.record_dataset_derivative_rebuild_terminal(v_request.id);
  end loop;
end
$$;

create temp table v2_read as
  select api.cmd_dataset_alias_execution_read_v2((select request_id from v2_ctx)) as result;
select is((select result->>'status' from v2_read), 'passed', 'a fully proved execution reads back as passed');
select is((select result->>'execution_status' from v2_read), 'completed', 'the stored lifecycle reaches completed through the child proofs');
select is(
  (select string_agg(key, ',' order by key) from jsonb_object_keys((select result->'terminal_proof' from v2_read)) as key),
  'audit,counts,plan_sha256,readback,status',
  'the terminal proof carries exactly its five keys'
);
select is((select result->'terminal_proof'->>'status' from v2_read), 'applied', 'the terminal proof reports applied');
select is(
  (select result->'terminal_proof'->>'plan_sha256' from v2_read),
  '3ed37f87d621a03237a3a0d004bf00403b3fbba292beebf0ea5bafadb1e276d5',
  'the terminal proof is bound to the reviewed plan digest'
);
select is(
  (select result->'terminal_proof'->'counts' from v2_read),
  (select request->'plan'->'expected' from v2_wire),
  'the terminal proof counts are exactly the plan expected block'
);
select is(
  (select result->'terminal_proof'->'audit'->>'batch_count' from v2_read),
  '1',
  'the audit block reports the plan batch count, not a per-table or per-chunk split'
);
select is(
  (select result->'terminal_proof'->'audit'->>'row_audit_count' from v2_read),
  '6',
  'the audit block counts one real ledger row audit per action'
);
select is(
  (select count(*)::integer from jsonb_array_elements((select result->'terminal_proof'->'audit'->'row_audits' from v2_read)) as audit_row
    where (audit_row->>'audit_id')::bigint is null),
  0,
  'every audit entry binds a real ledger identifier'
);
select is(
  (select count(*)::integer from jsonb_array_elements((select result->'terminal_proof'->'audit'->'row_audits' from v2_read)) as audit_row
    join private.command_audit_log as ledger on ledger.id = (audit_row->>'audit_id')::bigint
    where ledger.payload->>'plan_sha256' is distinct from (select plan_sha256 from v2_ctx)
       or ledger.actor_user_id is distinct from 'c536ee37-64ab-427b-b7e3-4e2bb4fdffb7'::uuid),
  0,
  'every audit entry names a ledger row of exactly this plan and actor'
);
select is(
  (select count(*)::integer from jsonb_array_elements((select result->'terminal_proof'->'readback'->'rows' from v2_read)) as row
    where row->>'observed_sha256' !~ '^[a-f0-9]{64}$'),
  0,
  'every readback row carries a canonical digest recomputed from the live row'
);
select is(
  (select count(*)::integer from jsonb_array_elements((select result->'terminal_proof'->'readback'->'rows' from v2_read)) as row
    join jsonb_array_elements((select request->'plan'->'actions' from v2_wire)) as action
      on action->>'id' = row->>'id' and action->>'table' = row->>'table'
    where row->>'observed_sha256' is distinct from private.dataset_alias_v2_payload_sha256(action->'desired_json_ordered')),
  0,
  'every live row observation equals the plan desired digest it claims'
);
select is(
  (select count(*)::integer from jsonb_array_elements((select result->'terminal_proof'->'readback'->'rows' from v2_read)) as row
    where row->>'table' = 'processes' and coalesce(row->>'functional_unit_text', '') = ''),
  0,
  'every process observation carries the functional-unit text read from the live row'
);
select is(
  (select result->'terminal_proof'->'readback'->>'row_count' from v2_read),
  '6',
  'the readback counts the live rows it observed'
);


-- ================================================================================================
-- 5. The public read must not keep reporting a successful current verification after the bound
--    support or the consumer set moves, and a restored snapshot must read back passed again.
--    (Database #680: the fresh closure now proves the current support and global occurrence closure.)
-- ================================================================================================
create temp table cc_changed_flow on commit drop as
  select a->>'id' as flow_id, a->>'version' as flow_version
  from jsonb_array_elements((select request->'plan'->'actions' from v2_wire)) as a
  where a->>'table' = 'flows'
  limit 1;

-- The canonical target unit-group factor changes after the completed run.
update public.unitgroups
set json_ordered = jsonb_set(json_ordered::jsonb, '{unitGroupDataSet,units,unit,1,meanValue}', to_jsonb('0.0002'::text), false)::json
where id = '49ce0c2f-2241-54e3-8e75-e75ffbdaecfb';
create temp table v2_drift_read on commit drop as select api.cmd_dataset_alias_execution_read_v2((select request_id from v2_ctx)) as result;
select is((select result->>'status' from v2_drift_read), 'failed',
  'drift: a changed canonical unit-group factor cannot read back passed');
select is((select result->'primary_readback'->>'live_closure_proof' from v2_drift_read), 'false',
  'drift: the public read reports the failed live closure');
select is((select result->'terminal_proof' from v2_drift_read), 'null'::jsonb,
  'drift: no terminal proof is emitted for a drifted run');
select is((select result->'primary_readback'->>'row_count' from v2_drift_read) is null, true,
  'drift: the drifted read reports no primary row count');
update public.unitgroups
set json_ordered = jsonb_set(json_ordered::jsonb, '{unitGroupDataSet,units,unit,1,meanValue}', to_jsonb('0.00011415525114155251'::text), false)::json
where id = '49ce0c2f-2241-54e3-8e75-e75ffbdaecfb';
create temp table v2_restore_read on commit drop as select api.cmd_dataset_alias_execution_read_v2((select request_id from v2_ctx)) as result;
select is((select result->>'status' from v2_restore_read), 'passed',
  'drift: restoring the exact snapshot restores the passed readback');
select is((select result->'primary_readback'->>'live_closure_proof' from v2_restore_read), 'true',
  'drift: the restored readback proves the live closure again');

